// Monta o pacote para o CRM, juntando as tres abas.
//
// Cada linha vai como uma LISTA na ordem das colunas (A, B, C...), e nao como
// objeto com nome de coluna. E de proposito: os titulos da planilha tem
// acento, quebra de linha e pelo menos um erro de digitacao (OBESERVACAO).
// Depender deles seria construir a ponte em cima de algo que muda quando
// alguem corrige um titulo.
//
// A aba de origem viaja junto: e ela que diz ao CRM se a cirurgia foi
// realizada ou cancelada, caso a situacao escrita na celula nao seja
// reconhecida.

const resposta = $input.first().json;
const faixas = resposta.valueRanges || [];

const linhas = [];
for (const faixa of faixas) {
  // range vem como "CIRURGIAS!A3:AE1000" — o nome da aba e o que vem antes do !
  const aba = String(faixa.range || '').split('!')[0].replace(/^'|'$/g, '');
  const valores = faixa.values || [];
  valores.forEach((v, i) => {
    if (String(v[2] || '').trim() === '') return;   // linha em branco no meio
    linhas.push({ aba, linha: i + 3, valores: v });
  });
}

const porAba = {};
for (const l of linhas) porAba[l.aba] = (porAba[l.aba] || 0) + 1;

// A aba CIRURGIAS crua viaja junto: e ela que sera mesclada na volta,
// celula a celula, preservando o que nao e do CRM.
const cirurgias = (faixas.find(f => String(f.range||'').startsWith('CIRURGIAS')) || {}).values || [];

return [{ json: { modo: 'completo', total: linhas.length, por_aba: porAba, linhas, planilha_cirurgias: cirurgias } }];

const r = $('Enviar ao CRM').first().json;
const m = $('Montar escrita').first().json;
return [{ json: {
  modo: r.modo,
  linhas_lidas_na_planilha: r.recebidas,
  cirurgias_criadas_no_crm: r.criadas,
  ja_existiam_ignoradas: r.ignoradas,
  erros: (r.erros || []).length,
  detalhe_dos_erros: r.erros || [],
  ESCREVEU_NA_PLANILHA: m.escrever,
  linhas_a_atualizar: m.vai_atualizar,
  linhas_a_incluir: m.vai_incluir,
  previa_das_mudancas: m.previa,
} }];

// ============================================================================
//  LIGA/DESLIGA DA ESCRITA NA PLANILHA
//  Deixe false para SIMULAR: o fluxo mostra o que mudaria sem tocar na planilha.
//  Troque para true depois de conferir a simulacao.
const ESCREVER_NA_PLANILHA = false;
// ============================================================================

// Monta o que sera gravado na aba CIRURGIAS.
//
// A regra que importa aqui: o CRM NAO escreve a linha inteira. Ele so escreve
// as colunas que sao dele; todas as outras sao copiadas da propria planilha,
// como estao. Sem isso, o carimbo do formulario, a coluna de alertas, o log da
// agenda e as cartas geradas seriam apagados na primeira sincronizacao.

const resposta = $('Enviar ao CRM').first().json;
const cruas = $('Preparar pacote').first().json.planilha_cirurgias || [];

const colunasDoCrm = new Set(resposta.colunas_do_crm || []);
const totalColunas = resposta.total_colunas || 31;
const COL_CRM_ID = 30;   // coluna AE

// Onde cada cirurgia ja esta na planilha, pelo id do CRM e nao pelo numero da
// linha: linha se move quando alguem insere ou apaga algo no meio.
const linhaPorId = {};
cruas.forEach((v, i) => {
  const id = String((v[COL_CRM_ID] || '')).trim();
  if (id) linhaPorId[id] = i + 3;          // a leitura comecou na linha 3
});

const atualizacoes = [];
const novas = [];
const previa = [];

for (const item of (resposta.linhas || [])) {
  const linhaExistente = linhaPorId[item.crm_id] || item.linha || null;
  const atual = linhaExistente ? (cruas[linhaExistente - 3] || []) : [];

  // Linha que ainda nao existe na planilha nao tem nada a preservar: vai
  // inteira como o CRM mandou, inclusive o carimbo de criacao.
  if (!linhaExistente) {
    novas.push(item.valores.slice(0, totalColunas));
    previa.push({ acao: 'incluir', linha: null, paciente: item.valores[2] });
    continue;
  }

  // Linha existente: valor do CRM nas colunas dele, valor da planilha no resto.
  const final = [];
  const mudou = [];
  for (let c = 0; c < totalColunas; c++) {
    const daPlanilha = atual[c] !== undefined ? atual[c] : '';
    const doCrm = item.valores[c] !== undefined ? item.valores[c] : '';
    const valor = colunasDoCrm.has(c) ? doCrm : daPlanilha;
    final.push(valor);
    if (colunasDoCrm.has(c) && String(valor) !== String(daPlanilha)) {
      mudou.push({ coluna: c, de: daPlanilha, para: valor });
    }
  }

  if (mudou.length === 0) continue;        // nada mudou nesta linha
  atualizacoes.push({ range: `CIRURGIAS!A${linhaExistente}:AE${linhaExistente}`, values: [final] });
  previa.push({ acao: 'atualizar', linha: linhaExistente, paciente: item.valores[2], mudancas: mudou.length, detalhe: mudou });
}

return [{ json: {
  escrever: ESCREVER_NA_PLANILHA,
  vai_atualizar: atualizacoes.length,
  vai_incluir: novas.length,
  previa,
  atualizacoes,
  novas,
} }];
